shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-dark: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b1;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --alert-red: #9e2a2b;
    --alert-red-soft: rgba(158, 42, 43, 0.1);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #284159;
    --cyber-green: #2b7a4b;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans-cn: 'Noto Sans SC', -apple-system, sans-serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-sans-en: 'Inter', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.78;
  }

  /* Reading Progress Bar */
  #progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    width: 0%;
    background: linear-gradient(90deg, var(--accent), var(--alert-red));
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.65rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }

  .wsj-monogram {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-decoration: none;
    border-right: 1px solid var(--line-strong);
    padding-right: 0.85rem;
  }

  .section-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.4rem;
  }

  .live-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: var(--alert-red);
    display: inline-block;
    box-shadow: 0 0 0 3px rgba(158, 42, 43, 0.2);
  }

  .nav-controls {
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  .chapter-jumps {
    display: flex;
    gap: 0.9rem;
    font-family: var(--font-sans-cn);
    font-size: 0.76rem;
    color: var(--muted);
  }

  .chapter-jumps a {
    color: var(--muted);
    text-decoration: none;
    transition: color 0.15s;
  }

  .chapter-jumps a:hover {
    color: var(--accent);
  }

  .lang-toggle {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 4px;
    overflow: hidden;
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.3rem 0.65rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.15s;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.2rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }

  .hero-kicker {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
  }

  .hero-kicker span.sep {
    color: var(--line-strong);
  }

  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(2.15rem, 4.4vw, 3.65rem);
    font-weight: 800;
    line-height: 1.18;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.15rem;
    max-width: 980px;
  }

  .hero-dek {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.15rem, 2vw, 1.45rem);
    line-height: 1.55;
    color: var(--muted);
    font-weight: 400;
    max-width: 840px;
    margin-bottom: 1.75rem;
  }

  :host([lang="en"]) .hero-dek {
    font-family: var(--font-serif-en);
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.1rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans-en);
    font-size: 0.84rem;
    color: var(--muted);
  }

  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }

  .byline-meta {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Telemetry Scale Strip */
  .telemetry-strip {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border-bottom: 1px solid var(--line-strong);
    background: var(--paper-card);
  }

  .telemetry-cell {
    padding: 1.35rem 1.5rem;
    border-right: 1px solid var(--line);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .telemetry-cell:last-child {
    border-right: none;
  }

  .telemetry-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.35rem;
  }

  .telemetry-num {
    font-family: var(--font-display);
    font-size: 2rem;
    font-weight: 800;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .telemetry-num.accent {
    color: var(--accent);
  }

  .telemetry-num.red {
    color: var(--alert-red);
  }

  .telemetry-desc {
    font-family: var(--font-sans-cn);
    font-size: 0.8rem;
    line-height: 1.45;
    color: var(--muted);
  }

  :host([lang="en"]) .telemetry-desc {
    font-family: var(--font-sans-en);
  }

  /* Main Asymmetric Editorial Layout */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2.8rem 1.5rem 4rem;
  }

  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 720px) minmax(280px, 380px);
    justify-content: space-between;
    gap: 3.2rem;
    align-items: start;
  }

  .prose-column {
    min-width: 0;
  }

  .sidebar-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2rem;
  }

  /* Prose Typography */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.5rem;
    letter-spacing: 0.01em;
  }

  :host([lang="zh-CN"]) .prose-p {
    line-height: 1.92;
    text-align: justify;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.8;
  }

  /* Lead Paragraph Treatment (No CSS ::first-letter on Chinese!) */
  .prose-p.lead-p {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 2px;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
    font-weight: 600;
  }

  /* Source Subheadings */
  h2.source-subhead {
    font-family: var(--font-display);
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--ink);
    margin: 2.8rem 0 1.25rem;
    padding-top: 1.6rem;
    border-top: 2px solid var(--ink);
    letter-spacing: -0.01em;
    position: relative;
  }

  h2.source-subhead::before {
    content: "SECTION DOSSIER";
    display: block;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 0.35rem;
  }

  /* Derived Pull Quote */
  blockquote.pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.4rem 1.35rem;
    margin: 0;
    position: relative;
  }

  blockquote.pull-quote::before {
    content: "VERIFIED QUOTE";
    display: block;
    font-family: var(--font-mono);
    font-size: 0.66rem;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 600;
    margin-bottom: 0.6rem;
  }

  .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.08rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  :host([lang="en"]) .quote-text {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
  }

  /* Reporter Context Dossier Card */
  .dossier-box {
    background: var(--navy-bg);
    color: #eae6df;
    padding: 1.5rem;
    border-radius: 2px;
    border-top: 3px solid var(--accent);
  }

  .dossier-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--navy-line);
    padding-bottom: 0.65rem;
    margin-bottom: 0.9rem;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    color: #e09f67;
    text-transform: uppercase;
  }

  .dossier-body {
    font-family: var(--font-sans-cn);
    font-size: 0.88rem;
    line-height: 1.75;
    color: #d7d2c8;
  }

  /* Bespoke SVG Forensic Cards */
  .forensic-figure {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
    margin: 1.8rem 0;
  }

  .forensic-figure.full-bleed {
    margin: 2.6rem 0;
    padding: 1.75rem;
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 2px solid var(--ink);
  }

  .figure-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 600;
    margin-bottom: 0.3rem;
  }

  .figure-title {
    font-family: var(--font-display);
    font-size: 1.22rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }

  .figure-sub {
    font-family: var(--font-sans-cn);
    font-size: 0.84rem;
    color: var(--muted);
    margin-bottom: 1.1rem;
    line-height: 1.5;
  }

  :host([lang="en"]) .figure-sub {
    font-family: var(--font-sans-en);
  }

  .figure-caption {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    margin-top: 0.85rem;
    padding-top: 0.65rem;
    border-top: 1px solid var(--line);
  }

  /* Theater Intelligence Matrix Table / Grid */
  .theater-matrix {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin: 2.2rem 0;
  }

  .theater-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
  }

  .theater-card.alert-top {
    border-top-color: var(--alert-red);
  }

  .theater-card.accent-top {
    border-top-color: var(--accent);
  }

  .theater-code {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .theater-name {
    font-family: var(--font-display);
    font-size: 1.12rem;
    font-weight: 700;
    color: var(--ink);
  }

  .theater-detail {
    font-family: var(--font-sans-cn);
    font-size: 0.85rem;
    line-height: 1.6;
    color: var(--body);
  }

  :host([lang="en"]) .theater-detail {
    font-family: var(--font-sans-en);
  }

  .theater-stat {
    margin-top: auto;
    padding-top: 0.75rem;
    border-top: 1px dashed var(--line-strong);
    font-family: var(--font-mono);
    font-size: 0.76rem;
    color: var(--accent);
    font-weight: 600;
  }

  /* Intercepted Videoconference Callout Box */
  .intercept-log {
    background: #17191c;
    color: #e5e2dc;
    border-left: 4px solid var(--alert-red);
    padding: 1.35rem 1.5rem;
    margin: 1.6rem 0 2rem;
    font-family: var(--font-mono);
  }

  .intercept-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.72rem;
    color: #f07167;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding-bottom: 0.6rem;
    margin-bottom: 0.8rem;
    border-bottom: 1px solid #2e3238;
  }

  /* Climactic Verdict Block */
  .verdict-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--ink);
    padding: 1.6rem 1.75rem;
    margin-top: 2rem;
  }

  .verdict-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.5rem;
    font-weight: 600;
  }

  .verdict-panel .prose-p {
    margin-bottom: 0;
    font-size: 1.18rem;
    font-weight: 600;
    color: var(--ink);
  }

  /* Footer */
  .ed-footer {
    border-top: 2px solid var(--ink);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    margin-top: 3rem;
  }

  .ed-footer-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1.5rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 960px) {
    .asymmetric-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .telemetry-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .telemetry-cell:nth-child(2) {
      border-right: none;
    }
    .telemetry-cell:nth-child(1),
    .telemetry-cell:nth-child(2) {
      border-bottom: 1px solid var(--line);
    }
    .theater-matrix {
      grid-template-columns: 1fr;
    }
    .chapter-jumps {
      display: none;
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.55rem 1rem;
    }
    .hero {
      padding: 2rem 1rem 1.75rem;
    }
    .editorial-container {
      padding: 1.8rem 1rem 3rem;
    }
    .telemetry-strip {
      grid-template-columns: 1fr;
    }
    .telemetry-cell {
      border-right: none !important;
      border-bottom: 1px solid var(--line);
      padding: 1.1rem 1rem;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .prose-p.lead-p {
      font-size: 1.12rem;
    }
    .forensic-figure,
    .forensic-figure.full-bleed {
      padding: 1rem;
    }
  }
